// Step 1: unpack the article draft sent by the website.
const payload = $json.body ?? $json;

const title = String(payload.title || '').trim();
const excerpt = String(payload.excerpt || '').trim();
const content = String(payload.content || '').trim();
const category = String(payload.category || '').trim();
const sourceUrl = String(payload.source_url || '').trim();
const requestedBy = payload.requested_by || {};

// Helper: safely parse URLs so invalid links do not break the workflow.
const parseUrl = (value) => {
  try {
    return new URL(String(value || '').trim());
  } catch (error) {
    return null;
  }
};

// Helper: only exact CNA/ST article pages count as trusted anchors.
const isExactTrustedArticleUrl = (value) => {
  const parsed = parseUrl(value);
  if (!parsed) return false;

  const host = parsed.hostname.toLowerCase();
  const allowedHosts = [
    'channelnewsasia.com',
    'www.channelnewsasia.com',
    'cna.com',
    'www.cna.com',
    'straitstimes.com',
    'www.straitstimes.com'
  ];
  if (!allowedHosts.includes(host)) return false;

  const path = parsed.pathname.replace(/\/+$/, '').toLowerCase();
  if (!path || path === '/') return false;

  const genericSegments = new Set([
    'singapore',
    'asia',
    'world',
    'business',
    'sport',
    'sports',
    'life',
    'opinion',
    'multimedia',
    'video',
    'videos',
    'podcasts',
    'newsletter',
    'news',
    'topic',
    'topics',
    'tag',
    'tags',
    'search',
    'live',
    'collection'
  ]);

  const segments = path.split('/').filter(Boolean);
  if (segments.length < 2) return false;
  if (segments.length === 1 && genericSegments.has(segments[0])) return false;
  if (segments.some((segment) => genericSegments.has(segment)) && segments.length < 3) return false;

  const lastSegment = segments[segments.length - 1];
  if (!/[a-z0-9-]{8,}/.test(lastSegment)) return false;

  return true;
};

// Map a trusted URL back to the outlet label used downstream.
const sourceNameFromUrl = (value) => {
  const host = parseUrl(value)?.hostname.toLowerCase() || '';
  if (host.includes('straitstimes.com')) return 'ST';
  if (host.includes('channelnewsasia.com') || host.includes('cna.com')) return 'CNA';
  return null;
};

// If the user gave an exact CNA/ST article, keep it as the primary evidence anchor.
const referenceValid = isExactTrustedArticleUrl(sourceUrl);
const referenceSource = referenceValid ? sourceNameFromUrl(sourceUrl) : null;
const primarySource = referenceValid && referenceSource
  ? {
      name: referenceSource,
      tier: 1,
      title: title || referenceSource,
      url: sourceUrl,
      snippet: excerpt || content.slice(0, 320),
      match_type: 'direct',
      relevance_note: 'primary_source_from_user_reference'
    }
  : null;

// Build one clean text block so the search step sees the whole draft in one prompt.
const articleText = [
  `Title: ${title || '[empty]'}`,
  `Category: ${category || '[empty]'}`,
  `Summary: ${excerpt || '[empty]'}`,
  `Reference URL: ${sourceUrl || '[none]'}`,
  'Content:',
  content || '[empty]'
].join('\n');

// Tell OpenAI search exactly what sources and JSON shape are allowed.
const searchPrompt = [
  'You are helping SharedSpace verify a user-submitted news draft.',
  'Search only CNA and The Straits Times.',
  'Find source articles that directly support, partially support, contradict, or strongly relate to the draft core story.',
  referenceValid
    ? `The user provided a valid exact ${referenceSource} article URL. Treat it as a trusted anchor and look for confirming or contradicting CNA/ST coverage of the same story.`
    : 'If the reference URL is missing, invalid, or generic, do not treat it as trusted evidence.',
  '',
  'Return ONLY valid JSON with this exact shape:',
  '{',
  '  "search_summary": "",',
  '  "matched_sources": [',
  '    {',
  '      "name": "CNA | ST",',
  '      "tier": 1,',
  '      "title": "",',
  '      "url": "",',
  '      "snippet": "",',
  '      "match_type": "direct | partial | related | contradicts",',
  '      "relevance_note": ""',
  '    }',
  '  ]',
  '}',
  '',
  'Rules:',
  '- Return at most 6 matched sources.',
  '- Allowed domains only: channelnewsasia.com, cna.com, straitstimes.com.',
  '- Prefer exact same-event matches over broad topic overlap.',
  '- Do not invent URLs, titles, snippets, or source names.',
  '- If no strong CNA/ST evidence is found, return an empty matched_sources array.',
  '',
  'Article draft:',
  articleText
].join('\n');

return [{
  json: {
    title,
    excerpt,
    content,
    category,
    source_url: sourceUrl,
    requested_by: requestedBy,
    reference_valid: referenceValid,
    reference_source: referenceSource,
    primary_source: primarySource,
    article_text: articleText,
    search_prompt: searchPrompt
  }
}];

// Step 2: wrap the search prompt in an OpenAI Responses API request.
const searchRequest = {
  model: 'gpt-5-mini',
  reasoning: { effort: 'low' },
  tools: [
    {
      type: 'web_search',
      filters: {
        allowed_domains: [
          'channelnewsasia.com',
          'www.channelnewsasia.com',
          'cna.com',
          'www.cna.com',
          'straitstimes.com',
          'www.straitstimes.com'
        ]
      }
    }
  ],
  tool_choice: 'auto',
  text: {
    format: {
      type: 'json_schema',
      name: 'sharedspace_cna_st_search',
      strict: true,
      schema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          search_summary: { type: 'string' },
          matched_sources: {
            type: 'array',
            items: {
              type: 'object',
              additionalProperties: false,
              properties: {
                name: { type: 'string' },
                tier: { type: 'integer' },
                title: { type: 'string' },
                url: { type: 'string' },
                snippet: { type: 'string' },
                match_type: { type: 'string' },
                relevance_note: { type: 'string' }
              },
              required: ['name', 'tier', 'title', 'url', 'snippet', 'match_type', 'relevance_note']
            }
          }
        },
        required: ['search_summary', 'matched_sources']
      }
    }
  },
  input: [
    {
      role: 'system',
      content: 'Return JSON only. Search only CNA and ST for article evidence relevant to the user draft. Do not score the draft in this step.'
    },
    {
      role: 'user',
      content: $json.search_prompt
    }
  ]
};

return [{ json: { ...$json, search_request: searchRequest } }];

// Step 3: parse the search model output and normalize every source into one shared shape.
const raw = $json.output_text || $json.output?.find((item) => item.type === 'message')?.content?.find((part) => part.type === 'output_text')?.text || '{}';
const cleaned = String(raw).replace(/```json|```/gi, '').trim();
let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  parsed = { search_summary: 'Search response could not be parsed.', matched_sources: [] };
}

const upstream = $items('Build Search Request', 0, 0)?.[0]?.json || {};

// Search can return slightly different outlet names, so normalize them back to CNA/ST.
const normalizeName = (name, url) => {
  const value = String(name || '').toLowerCase();
  const link = String(url || '').toLowerCase();
  if (value.includes('cna') || value.includes('channel newsasia') || link.includes('channelnewsasia.com') || link.includes('cna.com')) return 'CNA';
  if (value === 'st' || value.includes('straits') || link.includes('straitstimes.com')) return 'ST';
  return String(name || '');
};

const normalizeSource = (source) => ({
  name: normalizeName(source.name, source.url),
  tier: 1,
  title: String(source.title || ''),
  url: String(source.url || ''),
  snippet: String(source.snippet || ''),
  match_type: String(source.match_type || 'related').toLowerCase(),
  relevance_note: String(source.relevance_note || '')
});

const searchSources = Array.isArray(parsed.matched_sources)
  ? parsed.matched_sources
      .slice(0, 6)
      .map(normalizeSource)
      .filter((source) => ['CNA', 'ST'].includes(source.name) && (source.title || source.url || source.snippet))
  : [];

// Merge the user's trusted reference article with search-discovered sources, without duplicates.
const allSources = [];
if (upstream.primary_source) {
  allSources.push(normalizeSource(upstream.primary_source));
}
for (const source of searchSources) {
  const key = `${source.name}|${source.url}`.toLowerCase();
  if (!allSources.some((item) => `${item.name}|${item.url}`.toLowerCase() === key)) {
    allSources.push(source);
  }
}

const matchedSources = allSources.slice(0, 6);

return [{
  json: {
    ...upstream,
    search_summary: String(parsed.search_summary || ''),
    matched_sources: matchedSources
  }
}];

// Step 5: parse the scoring model output and apply SharedSpace's hard caps/bonuses.
const raw = $json.output_text || $json.output?.find((item) => item.type === 'message')?.content?.find((part) => part.type === 'output_text')?.text || '{}';
const cleaned = String(raw).replace(/```json|```/gi, '').trim();
const upstream = $items('Build Compare Request', 0, 0)?.[0]?.json || {};

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  return [{
    json: {
      trust_score: 0,
      publish_decision: 'unreliable',
      summary: 'Verification failed because the scoring response could not be parsed.',
      verdict: 'Unreliable. The verification response was invalid, so the draft cannot be trusted yet.',
      confidence: 0,
      reference_valid: Boolean(upstream.reference_valid),
      metrics: {
        factual_accuracy: 0,
        source_quality: 0,
        bias_detection: 0,
        logical_consistency: 0,
        completeness: 0
      },
      rubric_metrics: {
        A_factual_accuracy: 0,
        S_source_quality: 0,
        B_bias: 0,
        L_logic: 0,
        C_completeness: 0
      },
      claims: [],
      source_validation: {
        cna_match: false,
        st_match: false
      },
      flags: ['invalid_ai_response'],
      source_label: 'Unable to parse the verification response.',
      misinformation_highlights: []
    }
  }];
}

const clamp = (value, max) => Math.max(0, Math.min(max, Number(value ?? 0) || 0));
const metrics = parsed.metrics || {};
const claims = Array.isArray(parsed.claims) ? parsed.claims : [];
const sourceValidation = parsed.source_validation || {};
const flags = Array.isArray(parsed.flags) ? [...parsed.flags] : [];
const contentLength = String(upstream.content || '').trim().length;
const lowInformation = flags.includes('low_information') || flags.includes('vague_claims') || contentLength < 150 || claims.length < 2;
const noTrustedMatch = flags.includes('no_trusted_match') || (!sourceValidation.cna_match && !sourceValidation.st_match);
const coreContradicted = flags.includes('core_claim_contradicted') || flags.includes('multiple_core_claims_contradicted');
const contradictedByBoth = flags.includes('contradicted_by_cna_and_st');
const highBias = flags.includes('high_bias');
const bothStrong = Boolean(sourceValidation.cna_match) && Boolean(sourceValidation.st_match) && !coreContradicted && !contradictedByBoth;
const referenceValid = Boolean(parsed.reference_valid ?? upstream.reference_valid);

// Start with the model's raw rubric marks.
let A = clamp(metrics.A_factual_accuracy, 45);
let S = clamp(metrics.S_source_quality, 25);
let B = clamp(metrics.B_bias, 10);
let L = clamp(metrics.L_logic, 10);
let C = clamp(metrics.C_completeness, 10);

// Then enforce the non-negotiable project rules after the model scores the draft.
if (lowInformation) {
  A = Math.min(A, 10);
  C = Math.min(C, 3);
  if (!flags.includes('low_information')) {
    flags.push('low_information');
  }
}
if (noTrustedMatch) {
  S = 0;
  if (!flags.includes('no_trusted_match')) {
    flags.push('no_trusted_match');
  }
}
if (coreContradicted) {
  A = Math.min(A, flags.includes('multiple_core_claims_contradicted') ? 10 : 20);
}

// Build the final trust score from the rubric plus the extra caps and bonuses.
let trust = A + S + B + L + C;
if (noTrustedMatch) {
  trust = Math.min(trust, 50);
}
if (coreContradicted) {
  trust = Math.min(trust, 49);
}
if (contradictedByBoth) {
  trust = Math.min(trust, 30);
}
if (lowInformation) {
  trust = Math.min(trust, 35);
}
if (highBias) {
  trust = Math.round(trust * 0.85);
}
if (bothStrong) {
  trust += 2;
}
if (referenceValid) {
  trust += 3;
}
trust = Math.max(0, Math.min(100, Math.round(trust)));

// Convert the numeric trust score into the publish path used by the app.
let publishDecision = 'unreliable';
if (!lowInformation && !coreContradicted && trust >= 81) {
  publishDecision = 'auto_publish';
} else if (trust >= 60) {
  publishDecision = 'needs_review';
}

const verdictMap = {
  auto_publish: 'Reliable. Auto publish approved because the CNA/ST evidence is strong enough for direct publication.',
  needs_review: 'Needs Review. Do not publish yet. The draft needs manual revision or stronger evidence before it can move forward.',
  unreliable: 'Unreliable. Do not publish. The draft contains unsupported, false, or insufficiently verified information.'
};

// This short summary is what the editor UI shows beside the score ring.
const summaryParts = [];
if (bothStrong) {
  summaryParts.push('Both CNA and ST support the core story.');
} else if (sourceValidation.cna_match || sourceValidation.st_match) {
  summaryParts.push('Only one trusted source strongly supports the draft, so confidence remains limited.');
} else {
  summaryParts.push('No trusted CNA/ST match clearly supports the core story.');
}
if (referenceValid) {
  summaryParts.push('The supplied reference URL appears to be a valid exact CNA/ST article link.');
} else if (upstream.source_url) {
  summaryParts.push('The supplied reference URL does not qualify as a trusted exact CNA/ST article link.');
}
if (lowInformation) {
  summaryParts.push('The draft is too vague or too thin to verify precisely.');
}
if (coreContradicted) {
  summaryParts.push('At least one core claim is contradicted by trusted coverage.');
}
if (highBias) {
  summaryParts.push('Emotionally loaded language lowered the bias score.');
}

// If the model forgets to quote bad lines, fall back to obviously weak/contradicted claims.
const fallbackHighlights = claims
  .filter((claim) => Number(claim.match_score ?? 1) <= 0.2)
  .slice(0, 5)
  .map((claim) => ({
    line: claim.text || null,
    reason: claim.reason || 'This claim is unsupported or contradicted by the trusted CNA/ST matches.',
    source: claim.source || null
  }));

const misinformationHighlights = publishDecision === 'unreliable'
  ? ((Array.isArray(parsed.misinformation_highlights) && parsed.misinformation_highlights.length ? parsed.misinformation_highlights : fallbackHighlights)
      .slice(0, 5)
      .map((item) => ({
        line: item?.line ? String(item.line) : null,
        reason: String(item?.reason || 'Unsupported or contradicted by trusted CNA/ST evidence.'),
        source: item?.source ? String(item.source) : null
      })))
  : [];

const sourceCount = (Array.isArray(upstream.matched_sources) ? upstream.matched_sources : []).length;
const sourceLabel = sourceCount
  ? `Compared against ${sourceCount} trusted CNA/ST source${sourceCount === 1 ? '' : 's'}.`
  : 'No trusted CNA/ST match found.';

return [{
  json: {
    trust_score: trust,
    publish_decision: publishDecision,
    summary: summaryParts.join(' ') || 'Verification completed using CNA and ST only.',
    verdict: verdictMap[publishDecision],
    confidence: clamp(parsed.confidence, 1),
    reference_valid: referenceValid,
    metrics: {
      factual_accuracy: Math.round((A / 45) * 100),
      source_quality: Math.round((S / 25) * 100),
      bias_detection: Math.round((B / 10) * 100),
      logical_consistency: Math.round((L / 10) * 100),
      completeness: Math.round((C / 10) * 100)
    },
    rubric_metrics: {
      A_factual_accuracy: Math.round(A),
      S_source_quality: Math.round(S),
      B_bias: Math.round(B),
      L_logic: Math.round(L),
      C_completeness: Math.round(C)
    },
    claims: claims.slice(0, 8).map((claim) => ({
      text: String(claim.text || ''),
      subject: claim.subject ?? null,
      value: claim.value ?? null,
      time: claim.time ?? null,
      match_score: clamp(claim.match_score, 1),
      confidence: clamp(claim.confidence, 1),
      source: claim.source ?? null,
      reason: String(claim.reason || ''),
      importance: String(claim.importance || 'minor')
    })),
    source_validation: {
      cna_match: Boolean(sourceValidation.cna_match),
      st_match: Boolean(sourceValidation.st_match)
    },
    flags,
    source_label: sourceLabel,
    misinformation_highlights: misinformationHighlights,
    matched_sources: upstream.matched_sources || []
  }
}];
